with SessionStats as (select session_id, count(case when page = '/checkout' then 1 end) as checkout_count, max(event_time) as last_event_time from web_events where duration_sec is not null group by session_id) select sessions.id, sessions.browser, sessions.device, SessionStats.checkout_count, SessionStats.last_event_time from sessions inner join SessionStats on sessions.id = SessionStats.session_id order by last_event_time desc;
